/* ============================================================
   LUMIS — Dark Ecommerce Stylesheet
   ============================================================ */

/* 1. Base & Reset
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* 2. CSS Custom Properties
   ============================================================ */
:root {
  --bg-base:       #0b0b0f;
  --bg-2:          #121218;
  --bg-3:          #1a1a23;
  --bg-4:          #22222e;
  --bg-5:          #2c2c3c;
  --border:        #2e2e40;
  --border-light:  #3a3a50;

  --accent:        #d4a843;
  --accent-hover:  #e8bc5a;
  --accent-dim:    rgba(212, 168, 67, 0.12);
  --accent-dim2:   rgba(212, 168, 67, 0.06);

  --text-primary:   #f0f0f5;
  --text-secondary: #9898b5;
  --text-muted:     #5a5a78;
  --text-inverse:   #0b0b0f;

  --deal-red:      #e05c5c;
  --deal-red-dim:  rgba(224, 92, 92, 0.12);
  --success:       #4ec994;

  --radius-sm:    4px;
  --radius:       8px;
  --radius-lg:   14px;
  --radius-xl:   20px;
  --radius-full: 9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,0.5);
  --shadow-md:  0 4px 16px rgba(0,0,0,0.6);
  --shadow-lg:  0 12px 40px rgba(0,0,0,0.7);
  --shadow-glow: 0 0 40px rgba(212,168,67,0.08);

  --font-sans:   -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-serif:  'Playfair Display', Georgia, 'Times New Roman', serif;

  --header-height: 64px;
  --container:   1280px;
  --section-gap: clamp(60px, 8vw, 100px);
}

/* 3. Typography
   ============================================================ */
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-base);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  line-height: 1.2;
  font-weight: 600;
  color: var(--text-primary);
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover { color: var(--accent); }

img, svg { display: block; }

ul { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input {
  font-family: inherit;
}

/* 4. Layout Utilities
   ============================================================ */
.container {
  width: 100%;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: clamp(16px, 4vw, 40px);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* 5. Skip Link
   ============================================================ */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1000;
  padding: 12px 24px;
  background: var(--accent);
  color: var(--text-inverse);
  font-weight: 600;
  border-radius: 0 0 var(--radius) 0;
  transform: translateY(-100%);
  transition: transform 0.2s ease;
  text-decoration: none;
}

.skip-link:focus {
  transform: translateY(0);
}

/* 6. Focus Styles
   ============================================================ */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* 7. Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: var(--radius);
  transition: background-color 0.2s, color 0.2s, border-color 0.2s, transform 0.15s, box-shadow 0.2s;
  white-space: nowrap;
  cursor: pointer;
  border: none;
  font-family: inherit;
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--accent);
  color: var(--text-inverse);
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: var(--text-inverse);
  box-shadow: 0 4px 20px rgba(212,168,67,0.3);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-light);
}

.btn-ghost:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-dim2);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  font-size: 0.8125rem;
  padding: 10px 20px;
}

.btn-outline:hover {
  border-color: var(--border-light);
  color: var(--text-primary);
  background: var(--bg-4);
}

.btn-add-cart {
  width: 100%;
  background: var(--bg-4);
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  padding: 10px 16px;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: var(--radius);
  transition: background-color 0.2s, border-color 0.2s, color 0.2s;
  cursor: pointer;
  font-family: inherit;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.btn-add-cart:hover,
.btn-add-cart:focus-visible {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--text-inverse);
}

.btn-add-cart.added {
  background: var(--success);
  border-color: var(--success);
  color: #0b2e1e;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  transition: color 0.2s, background-color 0.2s;
  position: relative;
  border: none;
  background: none;
  cursor: pointer;
  flex-shrink: 0;
}

.icon-btn:hover { color: var(--text-primary); background: var(--bg-4); }
.icon-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* 8. Header
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
  background: rgba(11, 11, 15, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  height: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}

.site-logo {
  display: flex;
  align-items: center;
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--text-primary);
  text-decoration: none;
  flex-shrink: 0;
  font-family: var(--font-serif);
}

.site-logo .logo-mark {
  width: 28px;
  height: 28px;
  background: var(--accent);
  border-radius: 50%;
  margin-right: 10px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.primary-nav {
  flex: 1;
  display: flex;
  align-items: center;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  padding: 6px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius);
  transition: color 0.2s, background-color 0.2s;
  text-decoration: none;
  letter-spacing: 0.02em;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-3); }
.nav-link[aria-current="page"] { color: var(--accent); }

.nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: none;
  transition: color 0.2s, background-color 0.2s;
}

.nav-toggle:hover { color: var(--text-primary); background: var(--bg-3); }
.nav-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 16px;
  height: 16px;
  background: var(--accent);
  color: var(--text-inverse);
  font-size: 0.625rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  pointer-events: none;
  transition: transform 0.2s;
}

.cart-badge[data-count="0"] { display: none; }

/* 9. Hero
   ============================================================ */
.hero {
  position: relative;
  min-height: clamp(480px, 80vh, 700px);
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  overflow: hidden;
  background: var(--bg-2);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(212,168,67,0.06) 0%, transparent 60%),
    radial-gradient(ellipse 50% 80% at 20% 20%, rgba(80,60,140,0.12) 0%, transparent 60%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  grid-column: 1;
  padding-block: clamp(60px, 8vw, 100px);
  padding-inline-start: clamp(16px, 4vw, 40px);
  padding-inline-end: 40px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 20px;
}

.hero-eyebrow::before {
  content: '';
  width: 24px;
  height: 1.5px;
  background: var(--accent);
  flex-shrink: 0;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 700;
  font-style: italic;
  line-height: 1.05;
  color: var(--text-primary);
  margin-bottom: 24px;
  letter-spacing: -0.01em;
}

.hero-desc {
  font-size: clamp(0.9375rem, 1.5vw, 1.0625rem);
  color: var(--text-secondary);
  max-width: 380px;
  margin-bottom: 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.hero-visual {
  position: relative;
  grid-column: 2;
  height: 100%;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-orb {
  position: absolute;
  width: min(480px, 90%);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212,168,67,0.08) 0%, rgba(212,168,67,0.02) 50%, transparent 70%);
  border: 1px solid rgba(212,168,67,0.1);
}

.hero-orb-inner {
  position: absolute;
  width: min(320px, 65%);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid rgba(212,168,67,0.08);
  background: radial-gradient(circle, rgba(212,168,67,0.04) 0%, transparent 70%);
}

.hero-product-showcase {
  position: relative;
  z-index: 2;
  width: min(260px, 70%);
}

.hero-product-showcase svg {
  width: 100%;
  height: auto;
  filter: drop-shadow(0 20px 60px rgba(212,168,67,0.08));
}

.hero-tag {
  position: absolute;
  bottom: -20px;
  right: 0;
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--shadow-md);
  white-space: nowrap;
}

.hero-tag-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--success);
  flex-shrink: 0;
  box-shadow: 0 0 8px var(--success);
}

.hero-tag-label { font-size: 0.8125rem; color: var(--text-secondary); }
.hero-tag-price { font-size: 1rem; font-weight: 600; color: var(--text-primary); }

/* 10. Section Commons
   ============================================================ */
.section-wrap {
  padding-block: var(--section-gap);
}

.section-wrap--alt {
  background: var(--bg-2);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: clamp(28px, 4vw, 44px);
  flex-wrap: wrap;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.125rem);
  font-weight: 700;
  color: var(--text-primary);
}

.section-subtitle {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color 0.2s, gap 0.2s;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
}

.section-link:hover { color: var(--accent); gap: 10px; }
.section-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

/* 11. Product Cards
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s, transform 0.25s, box-shadow 0.25s;
}

.product-card:hover {
  border-color: var(--border-light);
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.product-image-wrap {
  position: relative;
  overflow: hidden;
  aspect-ratio: 4/5;
}

.product-image-wrap a {
  display: block;
  height: 100%;
}

.product-img {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.4s ease;
}

.product-card:hover .product-img { transform: scale(1.03); }

.product-img svg {
  width: 55%;
  height: auto;
  flex-shrink: 0;
}

.product-img--coat   { background: linear-gradient(140deg, #0f0e1c 0%, #1a1035 55%, #2d1b54 100%); }
.product-img--shoe   { background: linear-gradient(140deg, #0b1628 0%, #102040 50%, #1a3568 100%); }
.product-img--watch  { background: linear-gradient(140deg, #0e0e10 0%, #1a1a1e 50%, #252520 100%); }
.product-img--tote   { background: linear-gradient(140deg, #190f12 0%, #2a1620 55%, #1f1015 100%); }

.product-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--deal-red);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  pointer-events: none;
}

.product-badge--new {
  background: var(--accent);
  color: var(--text-inverse);
}

.product-wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(11,11,15,0.7);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: color 0.2s, background-color 0.2s, border-color 0.2s;
  cursor: pointer;
  backdrop-filter: blur(4px);
}

.product-wishlist:hover {
  color: var(--deal-red);
  border-color: var(--deal-red);
  background: rgba(224,92,92,0.1);
}

.product-wishlist:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.product-wishlist[aria-pressed="true"] { color: var(--deal-red); }

.product-info {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.product-category {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.product-name {
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.35;
  margin-top: 2px;
}

.product-name a {
  color: var(--text-primary);
  text-decoration: none;
  transition: color 0.2s;
}

.product-name a:hover { color: var(--accent); }
.product-name a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 4px;
}

.product-price-group {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.product-price {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
}

.product-price-original {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 4px;
}

.stars {
  display: flex;
  gap: 1px;
  color: var(--accent);
}

.stars svg { width: 12px; height: 12px; }

.review-count {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* 12. Deals Section
   ============================================================ */
.deals-section {
  background: var(--bg-2);
  padding-block: var(--section-gap);
}

.countdown {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--text-primary);
}

.countdown-segment {
  display: inline-block;
  min-width: 2ch;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.deal-card {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s, transform 0.25s, box-shadow 0.25s;
}

.deal-card:hover {
  border-color: var(--border-light);
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.deal-img {
  aspect-ratio: 16/10;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  position: relative;
  overflow: hidden;
}

.deal-img--1 { background: linear-gradient(135deg, #0d1f12 0%, #162e1c 50%, #102518 100%); }
.deal-img--2 { background: linear-gradient(135deg, #1a180d 0%, #28260f 50%, #1d1c0d 100%); }
.deal-img--3 { background: linear-gradient(135deg, #150d1e 0%, #22112e 50%, #180e22 100%); }

.deal-img svg {
  width: 44%;
  height: auto;
  position: relative;
  z-index: 1;
}

.deal-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 70% at 50% 50%, rgba(255,255,255,0.03) 0%, transparent 60%);
  pointer-events: none;
}

.deal-info {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.deal-discount {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  background: var(--deal-red-dim);
  color: var(--deal-red);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  align-self: flex-start;
}

.deal-name {
  font-size: 1.0625rem;
  font-weight: 600;
}

.deal-name a { color: var(--text-primary); transition: color 0.2s; }
.deal-name a:hover { color: var(--accent); }
.deal-name a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

.deal-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

.deal-prices {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 4px;
}

.deal-price-now { font-size: 1.25rem; font-weight: 700; color: var(--text-primary); }
.deal-price-was { font-size: 0.875rem; color: var(--text-muted); text-decoration: line-through; }

/* 13. Editorial Section
   ============================================================ */
.editorial-section {
  padding-block: var(--section-gap);
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 20px;
  align-items: start;
}

.editorial-card {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s, transform 0.25s, box-shadow 0.25s;
}

.editorial-card:hover {
  border-color: var(--border-light);
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.editorial-img {
  aspect-ratio: 4/3;
  display: flex;
  align-items: flex-end;
  justify-content: flex-start;
  padding: 24px;
  position: relative;
  overflow: hidden;
}

.editorial-card--lead .editorial-img {
  aspect-ratio: 16/11;
}

.editorial-img--1 {
  background: linear-gradient(160deg, #0d1827 0%, #162439 50%, #1e3050 100%);
}
.editorial-img--2 {
  background: linear-gradient(160deg, #1a0e13 0%, #28151e 50%, #201018 100%);
}
.editorial-img--3 {
  background: linear-gradient(160deg, #0d1a0e 0%, #152818 50%, #102015 100%);
}

.editorial-img svg {
  width: 50%;
  height: auto;
  opacity: 0.5;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.editorial-tag {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  background: rgba(212,168,67,0.15);
  border: 1px solid rgba(212,168,67,0.2);
  backdrop-filter: blur(4px);
  color: var(--accent);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
}

.editorial-info {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.editorial-meta-sep { color: var(--border-light); }

.editorial-title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.35;
}

.editorial-card--lead .editorial-title {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 2vw, 1.4375rem);
}

.editorial-title a { color: var(--text-primary); transition: color 0.2s; }
.editorial-title a:hover { color: var(--accent); }
.editorial-title a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--accent);
  margin-top: 4px;
  text-decoration: none;
  transition: gap 0.2s;
}

.editorial-read-more:hover { gap: 10px; }
.editorial-read-more:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

/* 14. Banner CTA Strip
   ============================================================ */
.banner-strip {
  background: var(--bg-4);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding-block: clamp(40px, 5vw, 64px);
  text-align: center;
}

.banner-strip .section-title {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: clamp(1.75rem, 4vw, 3rem);
  margin-bottom: 12px;
}

.banner-strip p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  margin-bottom: 28px;
}

/* 15. Footer
   ============================================================ */
.site-footer {
  background: var(--bg-2);
  border-top: 1px solid var(--border);
  padding-top: clamp(48px, 7vw, 80px);
  padding-bottom: 0;
}

.footer-top {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1.6fr;
  gap: clamp(32px, 4vw, 56px);
  padding-bottom: clamp(40px, 5vw, 60px);
  border-bottom: 1px solid var(--border);
}

.footer-brand .site-logo {
  font-size: 1.25rem;
  margin-bottom: 14px;
  display: inline-flex;
}

.footer-tagline {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
}

.footer-social {
  display: flex;
  gap: 8px;
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-secondary);
  transition: color 0.2s, border-color 0.2s, background-color 0.2s;
}

.social-link:hover { color: var(--text-primary); border-color: var(--border-light); background: var(--bg-4); }
.social-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.footer-nav-heading {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.footer-nav-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-nav-list a {
  font-size: 0.9rem;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.2s;
}

.footer-nav-list a:hover { color: var(--text-primary); }
.footer-nav-list a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

.footer-newsletter-heading {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.footer-newsletter-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 18px;
}

.newsletter-form { }

.newsletter-input-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.newsletter-input-group input[type="email"] {
  flex: 1;
  min-width: 0;
  padding: 10px 14px;
  background: var(--bg-base);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.875rem;
  transition: border-color 0.2s;
  min-width: 160px;
}

.newsletter-input-group input[type="email"]::placeholder { color: var(--text-muted); }

.newsletter-input-group input[type="email"]:focus {
  outline: none;
  border-color: var(--accent);
}

.newsletter-status {
  font-size: 0.8125rem;
  margin-top: 10px;
  min-height: 20px;
}

.newsletter-status.success { color: var(--success); }
.newsletter-status.error   { color: var(--deal-red); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-block: 24px;
  flex-wrap: wrap;
}

.copyright {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.legal-links {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.legal-links a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.2s;
}

.legal-links a:hover { color: var(--text-secondary); }
.legal-links a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

/* 16. Live Region
   ============================================================ */
#sr-live {
  position: absolute;
  left: -9999px;
  width: 1px;
  height: 1px;
  overflow: hidden;
}

/* 17. Responsive
   ============================================================ */
@media (max-width: 1100px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial-card--lead {
    grid-column: span 2;
  }
  .footer-top {
    grid-template-columns: 1fr 1fr;
    row-gap: 40px;
  }
  .footer-brand {
    grid-column: span 2;
    max-width: 420px;
  }
  .footer-newsletter {
    grid-column: span 2;
  }
}

@media (max-width: 768px) {
  .hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .hero-visual {
    display: none;
  }
  .hero-content {
    grid-column: 1;
    padding-block: 60px;
    padding-inline-end: clamp(16px, 4vw, 40px);
  }

  .deals-grid {
    grid-template-columns: 1fr;
  }
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-card--lead {
    grid-column: auto;
  }

  .primary-nav .nav-links {
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--bg-base);
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    padding: 12px 16px 20px;
    gap: 2px;
    transform: translateY(-120%);
    opacity: 0;
    transition: transform 0.3s ease, opacity 0.25s ease;
    z-index: 99;
    box-shadow: var(--shadow-lg);
  }

  .primary-nav .nav-links.is-open {
    transform: translateY(0);
    opacity: 1;
  }

  .primary-nav .nav-link {
    padding: 10px 14px;
    border-radius: var(--radius);
  }

  .nav-toggle { display: flex; }
}

@media (max-width: 600px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }
  .footer-brand,
  .footer-newsletter {
    grid-column: auto;
  }

  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .legal-links { gap: 16px; }
}

@media (max-width: 360px) {
  .products-grid {
    grid-template-columns: 1fr;
  }
}

/* 18. Forced Colors / High Contrast
   ============================================================ */
@media (forced-colors: active) {
  .product-card,
  .deal-card,
  .editorial-card {
    border: 1px solid ButtonText;
  }
  .btn-primary {
    background: Highlight;
    color: HighlightText;
    forced-color-adjust: none;
  }
  .btn-ghost {
    border-color: ButtonText;
  }
  .cart-badge {
    background: Highlight;
    color: HighlightText;
    forced-color-adjust: none;
  }
  .deal-discount {
    border: 1px solid ButtonText;
    color: ButtonText;
    background: none;
  }
  .hero::before { display: none; }
  .skip-link {
    background: Highlight;
    color: HighlightText;
    forced-color-adjust: none;
  }
}

