+}
+
+.product-badge--new {
+  background: var(--accent);
+  color: var(--text-inverse);
+}
+
+.product-wishlist {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  width: 32px;
+  height: 32px;
+  border-radius: 50%;
