+
+.footer-brand .site-logo {
+  font-size: 1.25rem;
+  margin-bottom: 14px;
+  display: inline-flex;
+}
+
+.footer-tagline {
+  font-size: 0.9375rem;
+  color: var(--text-secondary);
+  line-height: 1.6;
+  margin-bottom: 20px;
