+/* 16. Live Region
+   ============================================================ */
+#sr-live {
+  position: absolute;
+  left: -9999px;
+  width: 1px;
+  height: 1px;
+  overflow: hidden;
+}
+
+/* 17. Responsive
+   ============================================================ */
+@media (max-width: 1100px) {
+  .products-grid {
+    grid-template-columns: repeat(2, 1fr);
+  }
+  .editorial-grid {
+    grid-template-columns: 1fr 1fr;
+  }
+  .editorial-card--lead {
+    grid-column: span 2;
+  }
+  .footer-top {
+    grid-template-columns: 1fr 1fr;
+    row-gap: 40px;
+  }
+  .footer-brand {
+    grid-column: span 2;
+    max-width: 420px;
+  }
+  .footer-newsletter {
+    grid-column: span 2;
+  }
+}
+
+@media (max-width: 768px) {
+  .hero {
+    grid-template-columns: 1fr;
+    min-height: auto;
+  }
+  .hero-visual {
+    display: none;
+  }
+  .hero-content {
+    grid-column: 1;
+    padding-block: 60px;
+    padding-inline-end: clamp(16px, 4vw, 40px);
+  }
+
+  .deals-grid {
+    grid-template-columns: 1fr;
+  }
+  .editorial-grid {
+    grid-template-columns: 1fr;
+  }
+  .editorial-card--lead {
+    grid-column: auto;
+  }
+
+  .primary-nav .nav-links {
+    position: fixed;
+    top: var(--header-height);
+    left: 0;
+    right: 0;
+    background: var(--bg-base);
+    border-bottom: 1px solid var(--border);
+    flex-direction: column;
+    align-items: stretch;
+    padding: 12px 16px 20px;
+    gap: 2px;
+    transform: translateY(-120%);
+    opacity: 0;
+    transition: transform 0.3s ease, opacity 0.25s ease;
+    z-index: 99;
+    box-shadow: var(--shadow-lg);
+  }
+
+  .primary-nav .nav-links.is-open {
+    transform: translateY(0);
+    opacity: 1;
+  }
+
+  .primary-nav .nav-link {
+    padding: 10px 14px;
+    border-radius: var(--radius);
