(function () {
  'use strict';

  /* ── Utilities ────────────────────────────────────────── */

  /** Announce a message to screen readers via the live region. */
  function announce(message) {
    const region = document.getElementById('sr-live');
    if (!region) return;
    // Clear then set to ensure repeated messages re-trigger AT.
    region.textContent = '';
    requestAnimationFrame(() => {
      region.textContent = message;
    });
  }

  /** Pad a number to two digits. */
  function pad(n) {
    return String(n).padStart(2, '0');
  }

  /* ── Mobile Navigation ────────────────────────────────── */

  const navToggleBtn = document.getElementById('nav-toggle-btn');
  const navLinks     = document.getElementById('nav-links');

  if (navToggleBtn && navLinks) {
    function openNav() {
      navToggleBtn.setAttribute('aria-expanded', 'true');
      navLinks.classList.add('is-open');
      navToggleBtn.setAttribute('aria-label', 'Close navigation menu');
      // Move focus to first nav link
      const firstLink = navLinks.querySelector('a');
      if (firstLink) firstLink.focus();
    }

    function closeNav() {
      navToggleBtn.setAttribute('aria-expanded', 'false');
      navLinks.classList.remove('is-open');
      navToggleBtn.setAttribute('aria-label', 'Open navigation menu');
    }

    function isNavOpen() {
      return navToggleBtn.getAttribute('aria-expanded') === 'true';
    }

    navToggleBtn.addEventListener('click', () => {
      isNavOpen() ? closeNav() : openNav();
    });

    // Close with Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && isNavOpen()) {
        closeNav();
        navToggleBtn.focus();
      }
    });

    // Close when a nav link is clicked (on mobile)
    navLinks.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        if (window.innerWidth < 769) closeNav();
      });
    });

    // Close on outside click
    document.addEventListener('click', (e) => {
      if (
        isNavOpen() &&
        !navToggleBtn.contains(e.target) &&
        !navLinks.contains(e.target)
      ) {
        closeNav();
      }
    });
  }

  /* ── Countdown Timer ──────────────────────────────────── */

  const hoursEl   = document.getElementById('cd-hours');
  const minutesEl = document.getElementById('cd-minutes');
  const secondsEl = document.getElementById('cd-seconds');

  if (hoursEl && minutesEl && secondsEl) {
    // Parse the initial display value as starting point
    let totalSeconds =
      parseInt(hoursEl.textContent, 10)   * 3600 +
      parseInt(minutesEl.textContent, 10) * 60   +
      parseInt(secondsEl.textContent, 10);

    // Fallback: 14h 37m if parsing failed
    if (isNaN(totalSeconds) || totalSeconds <= 0) {
      totalSeconds = 14 * 3600 + 37 * 60;
    }

    function updateCountdown() {
      if (totalSeconds <= 0) {
        hoursEl.textContent   = '00';
        minutesEl.textContent = '00';
        secondsEl.textContent = '00';
        clearInterval(timerId);
        return;
      }
      totalSeconds--;

      const h = Math.floor(totalSeconds / 3600);
      const m = Math.floor((totalSeconds % 3600) / 60);
      const s = totalSeconds % 60;

      hoursEl.textContent   = pad(h);
      minutesEl.textContent = pad(m);
      secondsEl.textContent = pad(s);
    }

    const timerId = setInterval(updateCountdown, 1000);
  }

  /* ── Cart ─────────────────────────────────────────────── */

  let cartCount = 0;
  const cartBtn   = document.getElementById('cart-btn');
  const cartBadge = document.getElementById('cart-count');

  function updateCartUI() {
    if (!cartBtn || !cartBadge) return;
